\label{fw:upper}
Algorithm~\ref{fw:algorithm}, denoted by $A_F$, is query-only,
terminates almost surely and samples \eqref{eq:forwardtarget} exactly.
There is a constant $C>0$, depending only on the fixed coefficient
class and primitive costs, such that for every $T>0$, $x\in\mathbb{R}^d$,
$m\ge1$ and the grid,
\begin{equation}\label{cx:forward-upper}
 \sup_{(b,\sigma)\in\mathcal F_T}\mathbb{E}\mathcal{W}_{A_F}\le C(t_m+m).
\end{equation}
The constant is uniform in the initial state, horizon and requested grid.

\label{bridge:general}
Algorithm~\ref{bridge:general-algorithm}, denoted by $A_B$, is
query-only, terminates almost surely and samples
\eqref{eq:bridgetarget} exactly for every $T>0$, $x,y\in\mathbb{R}^d$,
$m\ge1$ and requested grid $0<t_1<\cdots<t_m<T$. There is a constant
$C>0$, depending only on the fixed coefficient class and primitive
costs, such that
\begin{equation}\label{br:general-work}
 \sup_{(b,\sigma)\in\mathcal F_T}\mathbb{E}\mathcal{W}_{A_B}
 \le C\{H_{T,x,y}^Q\log(2+H_{T,x,y})+m\}.
\end{equation}
The constant is uniform in the horizon, endpoints and requested grid.

\label{main:rates}\label{cx:rates}
The algorithms $A_F$ and $A_B$ of Theorems~\ref{fw:upper}
and~\ref{bridge:general} are admissible. There are constants $c,C>0$,
depending only on the fixed coefficient class and primitive costs,
such that the following hold.
\begin{enumerate}
\item[\rm(i)] For every $x\in\mathbb{R}^d$, $T>0$ and $m\ge1$,
\begin{equation*}
 \begin{aligned}
 c(T+m)&\le\mathfrak R_F^x(T,m)\le\sup_{\substack{(b,\sigma)\in\mathcal F_T\\
                      \mathbf t\in\mathcal G_F(T,m)}}
       \mathbb{E}_{b,\sigma}\mathcal{W}_{A_F}(T,x,\mathbf t)
 \le C(T+m).
 \end{aligned}
\end{equation*}
Thus $A_F$ is minimax optimal jointly in $T$ and $m$.

\item[\rm(ii)] For every fixed $T>0$ and $x,y\in\mathbb{R}^d$, there is
a finite constant $C_{T,|y-x|}>0$, depending only on $T$, $|y-x|$,
the coefficient class and primitive costs, such that for all $m\ge1$,
\begin{equation}\label{cx:bridge-rate}
 \begin{aligned}
 cm&\le\mathfrak R_B^{x,y}(T,m)\le\sup_{\substack{(b,\sigma)\in\mathcal F_T\\\mathbf t\in\mathcal G_B(T,m)}}
       \mathbb{E}_{b,\sigma}\mathcal{W}_{A_B}(T,x,y,\mathbf t)
 \le C_{T,|y-x|}m.
 \end{aligned}
\end{equation}
Consequently, $A_B$ is minimax optimal in $m$ for fixed $T,x,y$.
\end{enumerate}

\label{br5:terminal-rejection-lower}
The preceding acceptance rule is implementable with a transition coin
and a known uniform comparison. The accepted prefix has the bridge
law on its grid, and $\mathbb{E}\nu_{\mathrm{tr}}=\frac{U_\Delta}{p(0,x;T,y)}.$
There are constants $c_1,c_2>0$, depending only on the coefficient
class and primitive costs, such that for every $T>0$, every $x$ and
every admissible $M$, this particular construction with $y=x$ satisfies
\begin{equation}\label{br5:terminal-rejection-work}
 \sup_{(b,\sigma)\in\mathcal F_T}\mathbb{E}\mathcal{W}_{\mathrm{tr}}
 \ge c_1e^{c_2T}.
\end{equation}

\label{br5:density-bounds}
There are computable class constants $c_*,C_*,C_{\mathrm{den}}>0$
and $\delta_*>0$ such that
\begin{equation}\label{br5:global-density}
 \begin{gathered}
 p_{T_0}=p(0,0;2n,0)\ge c_*e^{-C_*n},\qquad n\ge1,\\
 \sup_{u,v}p(s,u;t,v)\le C_{\mathrm{den}}\delta^{-d/2}
 \quad\text{if }t-s\ge\delta,\quad0<\delta\le\delta_*.
 \end{gathered}
\end{equation}
